// Endpoint item/list.do tidak mengembalikan field itemCategory (parameter fields diabaikan),
// jadi kategori dikenali dari nama produk.
// Dua level dikeluarkan:
//   brandItem    -> selalu level lini/brand, dipakai untuk agregasi laporan (konsisten)
//   kategoriItem -> kategori penuh kalau namanya cocok, kalau tidak jatuh ke brand

const KATEGORI_DIIZINKAN = [
  'Abqori','Adnan Kurma','Adnan Puzzle','Ahsan Anak','Ahsan Bulat','Ahsan JUMBO',
  'Ahsan KIDS','Ahsan REG','Ahsan Remaja','Alfan REG','Alfan Remaja','Althaff Jumbo',
  'Althaff Reguler','Arkan','Asyraf','Ayyas','Ghazwan Panjang','Jubah Reguler',
  'JUMBO Adnan Kurma','JUMBO Ghazwan Panjang','JUMBO Ghazwan Pendek','Jumbo QAID',
  'JUMBO Qassam','JUMBO Qotadah','JUMBO Syamil','Kemko Farouq','Kurta Bassam',
  'Kurta Haneef','Qotadah','Shabrina Nahla','Slimfit Arsalan','Slimfit Ghaisan',
  'Slimfit Qashwa','Slimfit Qayyim','Syamil REG'
];

// Kata JUMBO, Slimfit, Kurta, Kemko hanya varian, bukan penentu lini.
// SHABRINA dan NAHLA menunjuk lini yang sama, jadi dipetakan ke satu label.
const BRAND = ['ABQORI','ADNAN','AHSAN','ALFAN','ALTHAFF','ARKAN','ARSALAN','ASYRAF',
  'AYYAS','BASSAM','FAROUQ','GHAISAN','GHAZWAN','HANEEF','JUBAH','NAHLA','QAID',
  'QASHWA','QASSAM','QAYYIM','QOTADAH','SHABRINA','SYAMIL'];
const setBrand = new Set(BRAND);
const ALIAS = { NAHLA: 'SHABRINA', SHABRINA: 'SHABRINA' };

const norm = (s) => String(s ?? '').trim().toUpperCase().replace(/\s+/g, ' ');
const rapi = (t) => t.charAt(0) + t.slice(1).toLowerCase();
// Kategori terpanjang dicek duluan supaya 'JUMBO Ghazwan Panjang' menang atas 'Ghazwan Panjang'
const kategoriUrut = [...KATEGORI_DIIZINKAN].sort((a, b) => b.length - a.length);

function cariKategori(teks) {
  for (const k of kategoriUrut) if (teks.startsWith(norm(k))) return k;
  return null;
}
function cariBrand(teks) {
  const token = teks.replace(/[(),\/]/g, ' ').split(/[\s-]+/).filter(Boolean);
  for (const t of token) if (setBrand.has(t)) return ALIAS[t] || t;
  return null;
}

// Bongkar pembungkus Accurate { s: true, d: [...] }
const baris = [];
for (const item of $input.all()) {
  const b = item.json;
  if (Array.isArray(b?.d)) baris.push(...b.d);
  else if (b) baris.push(b);
}

const lolos = [];
const tertolak = new Map();

for (const row of baris) {
  const teks = norm(row.name || row.no);
  const kategori = cariKategori(teks);
  const brand = cariBrand(teks);

  if (kategori || brand) {
    const labelBrand = brand ? rapi(brand) : kategori;
    lolos.push({ json: { ...row, brandItem: labelBrand, kategoriItem: kategori || labelBrand } });
  } else {
    const key = teks.split(' ').slice(0, 2).join(' ') || '(tanpa nama)';
    tertolak.set(key, (tertolak.get(key) || 0) + 1);
  }
}

console.log('Baris masuk:', baris.length, '| lolos:', lolos.length, '| tertolak:', baris.length - lolos.length);
console.log('Contoh yang dibuang:', [...tertolak.entries()].sort((a, b) => b[1] - a[1]).slice(0, 20));

return lolos;

// ============================================================
// Node: Normalisasi Sales
// Mode: Run Once for All Items
// Input : Gabung Sheet VS (boleh berisi lebih dari satu sheet VS,
//         termasuk dari spreadsheet yang berbeda)
// Output: 1 item { _source:'sales', bulanBerjalan, bulanSebelumnya, tahunLalu }
//
// CARA KERJA
// 1. Baris dikelompokkan per sheet asal memakai sidik jari kolom, yaitu
//    daftar judul blok "DATA PENJUALAN <BULAN> <TAHUN>" yang dimiliki
//    baris itu. Ini penting karena dua spreadsheet berbeda memakai
//    penomoran kolom sendiri-sendiri. Tanpa pemisahan ini, baris sheet
//    September akan terbaca memakai peta kolom sheet Juli dan angkanya
//    tercampur tanpa error apa pun.
// 2. Di dalam tiap kelompok, blok dideteksi dari judul kolomnya dan
//    tujuh kolom sesudahnya diambil berdasarkan urutan kolom.
// 3. Pemilihan bulan berjalan mengikuti tanggal hari ini. Menambah blok
//    atau menambah sheet baru tidak perlu mengubah kode.
// ============================================================

const POLA_BLOK = /^DATA PENJUALAN\s+([A-Za-z]+)\s+(\d{4})\s*$/i;

const rowsMasuk = $input.all()
  .map(i => i.json)
  .filter(r => r && typeof r === 'object');

// ---------- helper ----------
const BLN = {
  jan: 1, feb: 2, mar: 3, apr: 4, mei: 5, may: 5, jun: 6, jul: 7,
  agu: 8, aug: 8, sep: 9, okt: 10, oct: 10, nov: 11, des: 12, dec: 12,
};
const NAMA_BULAN = ['JANUARI', 'FEBRUARI', 'MARET', 'APRIL', 'MEI', 'JUNI',
  'JULI', 'AGUSTUS', 'SEPTEMBER', 'OKTOBER', 'NOVEMBER', 'DESEMBER'];

function num(v) {
  if (v === null || v === undefined) return 0;
  if (typeof v === 'number') return isFinite(v) ? v : 0;
  let s = String(v).trim();
  if (!s || s === '-' || s === '#DIV/0!' || s === '#N/A') return 0;
  s = s.replace(/rp/ig, '').replace(/\s/g, '');
  const persen = s.includes('%');
  s = s.replace('%', '');
  if (/,/.test(s) && /\./.test(s)) s = s.replace(/\./g, '').replace(',', '.');
  else if (/,/.test(s)) s = s.replace(',', '.');
  const n = parseFloat(s);
  if (!isFinite(n)) return 0;
  return persen ? n / 100 : n;
}

function isKosong(v) {
  return v === '' || v === null || v === undefined;
}

function parseTgl(v, defaultYear) {
  if (typeof v !== 'string') return null;
  const m = v.trim().match(/^(\d{1,2})[-\s\/]([A-Za-z]{3,})\.?(?:[-\s\/](\d{2,4}))?$/);
  if (!m) return null;
  const bln = BLN[m[2].slice(0, 3).toLowerCase()];
  if (!bln) return null;
  let th = m[3] ? parseInt(m[3], 10) : defaultYear;
  if (th < 100) th += 2000;
  return `${th}-${String(bln).padStart(2, '0')}-${String(m[1]).padStart(2, '0')}`;
}

// ---------- 1. kelompokkan baris per sheet asal ----------
function sidikSheet(r) {
  return Object.keys(r).filter(k => POLA_BLOK.test(k)).join('|');
}

const kelompok = new Map();
for (const r of rowsMasuk) {
  const sidik = sidikSheet(r);
  if (!sidik) continue;              // bukan baris sheet VS
  if (!kelompok.has(sidik)) kelompok.set(sidik, []);
  kelompok.get(sidik).push(r);
}

// ---------- 2. deteksi blok di tiap kelompok ----------
const BLOKS = [];
for (const [sidik, baris] of kelompok.entries()) {
  // Kolom diambil dari baris terlengkap di kelompok ini saja.
  let kolom = [];
  for (const r of baris) {
    const k = Object.keys(r);
    if (k.length > kolom.length) kolom = k;
  }
  for (let i = 0; i < kolom.length; i++) {
    const m = String(kolom[i]).match(POLA_BLOK);
    if (!m) continue;
    const bln = BLN[m[1].slice(0, 3).toLowerCase()];
    if (!bln) continue;              // buang judul seperti DATA PENJUALAN PERPEKAN
    const sesudah = kolom.slice(i + 1, i + 8);
    if (sesudah.length < 7) continue;
    const tahun = parseInt(m[2], 10);
    BLOKS.push({
      sidik, baris,
      kunciBulan: `${tahun}-${String(bln).padStart(2, '0')}`,
      label: `${NAMA_BULAN[bln - 1]} ${tahun}`,
      tahun,
      kunci: kolom[i],
      omset: sesudah[0], resi: sesudah[1], terjual: sesudah[2],
      shopee: sesudah[3], tiktok: sesudah[4], lazada: sesudah[5], lainnya: sesudah[6],
    });
  }
}

// ---------- 3. parse tiap blok ----------
const hasil = {};

for (const B of BLOKS) {
  const harian = [];
  const kv = {};
  const flat = {};
  let section = 'RINGKASAN';

  for (const r of B.baris) {
    // Pengaman terakhir: baris yang tidak memuat judul blok ini bukan
    // miliknya, walaupun kebetulan punya nama kolom yang sama.
    if (!(B.kunci in r)) continue;

    const kunciVal = r[B.kunci];
    const labelVal = r[B.omset];
    const nilaiVal = r[B.resi];

    const tgl = parseTgl(kunciVal, B.tahun);
    if (tgl) {
      harian.push({
        tanggal: tgl,
        omset: num(r[B.omset]),
        resi: num(r[B.resi]),
        terjual: num(r[B.terjual]),
        shopee: num(r[B.shopee]),
        tiktok: num(r[B.tiktok]),
        lazada: num(r[B.lazada]),
        lainnya: num(r[B.lainnya]),
      });
      continue;
    }

    const label = !isKosong(kunciVal) ? String(kunciVal).trim()
                : !isKosong(labelVal) ? String(labelVal).trim()
                : null;
    if (!label) continue;
    if (label.length > 60) continue;

    const kapital = label === label.toUpperCase() && /[A-Z]/.test(label);
    if (label === 'VARIABLE' || (isKosong(nilaiVal) && kapital)) {
      section = label.toUpperCase();
      if (!kv[section]) kv[section] = {};
      continue;
    }
    if (isKosong(nilaiVal)) continue;

    if (!kv[section]) kv[section] = {};
    const nilai = typeof nilaiVal === 'number' ? nilaiVal : num(nilaiVal);
    kv[section][label] = nilai;
    if (!(label in flat)) flat[label] = nilai;
  }

  const totOmset = harian.reduce((a, d) => a + d.omset, 0);
  const totTerjual = harian.reduce((a, d) => a + d.terjual, 0);

  const blok = {
    periode: B.label,
    kunciBulan: B.kunciBulan,
    hariTerisi: harian.length,
    harian,
    ringkasan: {
      totalOmset: flat['Total Omset'] || totOmset,
      totalResi: flat['Resi'] || harian.reduce((a, d) => a + d.resi, 0),
      totalTerjual: flat['Produk Terjual'] || totTerjual,
      spendAdsPpn: flat['Spend Ads +ppn'] || 0,
      metaAds: flat['Meta Ads'] || 0,
      komisiAffiliate: flat['Komisi Affiliate'] || 0,
      koinPenjual: flat['Koin penjual'] || 0,
      biayaPromosiPerPcs: flat['Biaya promosi/pcs'] || 0,
      roasTotal: flat['ROAS total'] || flat['ROAS TOTAL'] || 0,
    },
    shopee: {
      omset: (kv['SHOPEE'] || kv['SHOPEE ALL'] || {})['Omset Shopee'] || 0,
      terjual: (kv['SHOPEE'] || kv['SHOPEE ALL'] || {})['Produk terjual'] || 0,
      ads: (kv['SHOPEE'] || kv['SHOPEE ALL'] || {})['Shopee Ads +ppn'] || 0,
      cpas: (kv['SHOPEE'] || kv['SHOPEE ALL'] || {})['CPAS ads+ppn'] || 0,
      komisi: (kv['SHOPEE'] || kv['SHOPEE ALL'] || {})['Komisi Affiliate'] || 0,
      biayaPerPcs: (kv['SHOPEE'] || kv['SHOPEE ALL'] || {})['Biaya promosi/pcs'] || 0,
      roas: (kv['SHOPEE'] || kv['SHOPEE ALL'] || {})['ROAS ~ Shopee']
         || (kv['SHOPEE'] || kv['SHOPEE ALL'] || {})['ROAS total'] || 0,
    },
    tiktok: {
      omset: (kv['TIKTOK'] || {})['Omset Tiktok'] || 0,
      terjual: (kv['TIKTOK'] || {})['Produk terjual'] || 0,
      ads: (kv['TIKTOK'] || {})['Tiktok Ads +ppn'] || 0,
      komisi: (kv['TIKTOK'] || {})['Komisi Affiliate'] || 0,
      biayaPerPcs: (kv['TIKTOK'] || {})['Biaya promosi/pcs'] || 0,
      roas: (kv['TIKTOK'] || {})['ROAS ~ Tiktok'] || (kv['TIKTOK'] || {})['ROAS total'] || 0,
    },
    meta: {
      spend: (kv['META ADS'] || {})['Spend'] || 0,
      ppn: (kv['META ADS'] || {})['PPN 11%'] || 0,
      total: (kv['META ADS'] || {})['TOTAL'] || 0,
      impresi: (kv['META ADS'] || {})['Impresi'] || 0,
      visit: (kv['META ADS'] || {})['Visit'] || 0,
      followersFanpage: (kv['META ADS'] || {})['Penambahan Followers Fanpages'] || 0,
      followersIg: (kv['META ADS'] || {})['Penambahan Followers IG'] || 0,
    },
    linktree: {
      totalView: (kv['VARIABLE'] || {})['Total View'] || 0,
      totalClick: (kv['VARIABLE'] || {})['Total Click'] || 0,
      klikShopee: (kv['VARIABLE'] || {})['- klik shopee'] || 0,
      klikWa: (kv['VARIABLE'] || {})['- klik WA'] || 0,
      klikMaps: (kv['VARIABLE'] || {})['- klik maps'] || 0,
      klikTiktok: (kv['VARIABLE'] || {})['- klik tiktok'] || 0,
      klikWebsite: (kv['VARIABLE'] || {})['- klik website'] || 0,
      biayaPerView: (kv['VARIABLE'] || {})['Biaya/view'] || 0,
      cpcTotal: (kv['VARIABLE'] || {})['Biaya/click (CPC Total)'] || 0,
    },
    _kv: kv,
  };

  // Bila dua sheet memuat bulan yang sama, menangkan yang datanya lebih
  // lengkap, bukan yang kebetulan diproses terakhir.
  const lama = hasil[B.kunciBulan];
  if (!lama || blok.hariTerisi > lama.hariTerisi) hasil[B.kunciBulan] = blok;
}

// ---------- 4. pilih blok berdasarkan tanggal hari ini ----------
function geser(kunciBulan, jumlahBulan) {
  const [y, m] = kunciBulan.split('-').map(Number);
  const d = new Date(Date.UTC(y, m - 1 + jumlahBulan, 1));
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}`;
}

const wib = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta' }));
const kunciSekarang = `${wib.getFullYear()}-${String(wib.getMonth() + 1).padStart(2, '0')}`;
const labelSekarang = `${NAMA_BULAN[wib.getMonth()]} ${wib.getFullYear()}`;

const tersedia = Object.keys(hasil).sort();
let kunciTerpakai = hasil[kunciSekarang] ? kunciSekarang : null;
const sesuaiBulanBerjalan = Boolean(kunciTerpakai);

if (!kunciTerpakai && tersedia.length) {
  kunciTerpakai = tersedia[tersedia.length - 1];
}

const bulanBerjalan = kunciTerpakai ? hasil[kunciTerpakai] : null;
const bulanSebelumnya = kunciTerpakai ? (hasil[geser(kunciTerpakai, -1)] || null) : null;
const tahunLalu = kunciTerpakai ? (hasil[geser(kunciTerpakai, -12)] || null) : null;

if (bulanBerjalan && !sesuaiBulanBerjalan) {
  bulanBerjalan.periode = bulanBerjalan.periode + ' \u00b7 bukan bulan berjalan';
}

const catatanPeriode = sesuaiBulanBerjalan
  ? null
  : `Sheet belum memuat blok "DATA PENJUALAN ${labelSekarang}". Angka yang ditampilkan berasal dari ${kunciTerpakai || 'tidak ada blok sama sekali'}.`;

return [{
  json: {
    _source: 'sales',
    bulanBerjalan,
    bulanSebelumnya,
    tahunLalu,
    periodeInfo: {
      bulanBerjalanSesungguhnya: kunciSekarang,
      labelBulanBerjalan: labelSekarang,
      blokDipakai: kunciTerpakai,
      sesuaiBulanBerjalan,
      blokTersedia: tersedia,
      jumlahSheetTerbaca: kelompok.size,
      jumlahBlokTerbaca: BLOKS.length,
      catatan: catatanPeriode,
    },
  },
}];

// ============================================================
// CODE NODE 2 — "Normalisasi Ads"
// Mode: Run Once for All Items
// Input : Google Sheets (sheet META ADS / harian per campaign)
// Output: 1 item { _source:'ads', iklan:[...], linktreeHarian:[...], leadsWa:[...] }
// ============================================================

const rows = $input.all().map(i => i.json);

const BLN = {
  jan:1, feb:2, mar:3, apr:4, mei:5, may:5, jun:6, jul:7,
  agu:8, aug:8, sep:9, okt:10, oct:10, nov:11, des:12, dec:12,
};

function num(v) {
  if (v === null || v === undefined) return 0;
  if (typeof v === 'number') return isFinite(v) ? v : 0;
  let s = String(v).trim();
  if (!s || s === '-' || s === '#DIV/0!' || s === '#N/A') return 0;
  s = s.replace(/rp/ig, '').replace(/\s/g, '');
  const persen = s.includes('%');
  s = s.replace('%', '');
  if (/,/.test(s) && /\./.test(s)) s = s.replace(/\./g, '').replace(',', '.');
  else if (/,/.test(s)) s = s.replace(',', '.');
  else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, ''); // 1.460 -> 1460
  const n = parseFloat(s);
  if (!isFinite(n)) return 0;
  return persen ? n / 100 : n;
}

// Sheet kadang mengirim "6.502" (pemisah ribuan ID) sebagai angka 6.502.
// Metrik volume tidak mungkin pecahan, jadi bulatkan balik ke ribuan.
function volume(v) {
  const n = num(v);
  if (n !== 0 && !Number.isInteger(n) && Math.abs(n) < 1000) {
    return Math.round(n * 1000);
  }
  return Math.round(n);
}

function isKosong(v) { return v === '' || v === null || v === undefined; }

function parseTgl(v, defaultYear) {
  if (isKosong(v)) return null;
  if (typeof v === 'number') return null;
  const s = String(v).trim();
  let m;
  // 13/06/2026
  if ((m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/))) {
    return `${m[3]}-${String(m[2]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`;
  }
  // 2026-07-01
  if ((m = s.match(/^(\d{4})-(\d{2})-(\d{2})/))) return `${m[1]}-${m[2]}-${m[3]}`;
  // 1-Jul / 27 Juli / 01-Jul-2026
  if ((m = s.match(/^(\d{1,2})[-\s]([A-Za-z]{3,})\.?(?:[-\s](\d{2,4}))?$/))) {
    const b = BLN[m[2].slice(0,3).toLowerCase()];
    if (!b) return null;
    let th = m[3] ? parseInt(m[3],10) : defaultYear;
    if (th < 100) th += 2000;
    return `${th}-${String(b).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`;
  }
  return null;
}

// tanggal di kolom Linktree/leads berformat US: 7/1/2026 = 1 Juli 2026
function parseTglUS(v) {
  if (isKosong(v)) return null;
  const m = String(v).trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (!m) return null;
  return `${m[3]}-${String(m[1]).padStart(2,'0')}-${String(m[2]).padStart(2,'0')}`;
}

// "Ahsan | 24 Juli | Instagram" -> produk "Ahsan", objective "Instagram"
function pecahCampaign(nama) {
  const raw = String(nama || '').trim();
  const bagian = raw.split('|').map(s => s.trim()).filter(Boolean);
  let produk = bagian[0] || raw;
  produk = produk
    .replace(/\d{1,2}[\/\-]\d{1,2}([\/\-]\d{2,4})?/g, '')
    .replace(/\b\d{1,2}\s*(jan|feb|mar|apr|mei|jun|juni|jul|juli|agu|agust|sep|okt|nov|des)\w*/ig, '')
    .replace(/\b(jan|feb|mar|apr|mei|jun|juni|jul|juli|agu|agust|sep|okt|nov|des)\w*\b/ig, '')
    .replace(/\s{2,}/g, ' ')
    .trim();
  if (!produk) produk = bagian[0] || raw;
  // samakan penulisan: PAYDAY / PayDay -> Payday, "Ahsan 2" -> Ahsan
  produk = produk.replace(/\s+\d+$/, '').trim();
  produk = produk.toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
  const objective = bagian.length > 2 ? bagian[bagian.length - 1] : '';
  return { produk, objective, campaign: raw };
}

const TAHUN = 2026;
const iklan = [];
const linktreeHarian = [];
const leadsWa = [];
const linktreeRingkasan = {};   // ringkasan bulan pertama (blok atas)

let skema = 'A';                // A = Followers, B = CTR/CPC
let tglAktif = null;
let tglLtAktif = null;
let tglWaAktif = null;

for (const r of rows) {
  if (!r || typeof r !== 'object') continue;

  // --- baris header ulang di tengah sheet -> ganti skema ---
  if (String(r['Nama Campaign']).trim() === 'Nama Campaign' ||
      String(r['Tanggal']).trim() === 'Tanggal') {
    skema = 'B';
    tglAktif = null;
    continue;
  }

  // ============ 1. tabel iklan harian per campaign ============
  const t = parseTgl(r['Tanggal'], TAHUN);
  if (t) tglAktif = t;                       // forward-fill tanggal
  const namaCamp = String(r['Nama Campaign'] || '').trim();

  if (namaCamp && tglAktif) {
    const { produk, objective, campaign } = pecahCampaign(namaCamp);
    const spend = num(r['Amount Spend']);
    const ppn = num(r['col_11']) || +(spend * 0.11).toFixed(2);
    const impression = volume(r['Impression']);
    const reach = volume(r['Reach']);
    const visit = volume(r['Instagram Visit']);

    iklan.push({
      tanggal: tglAktif,
      campaign,
      produk,
      objective,
      spend,
      ppn,
      spendPpn: +(spend + ppn).toFixed(2),
      impression,
      reach,
      igVisit: visit,
      chatWa: skema === 'A' ? num(r['Chat WA']) : 0,
      followersFanpage: skema === 'A' ? num(r['Followers FanPage']) : 0,
      followersIg: skema === 'A' ? num(r['Followers IG']) : num(r['Chat WA']),
      ctr: skema === 'B' ? num(r['Followers FanPage']) : (impression ? visit / impression : 0),
      cpc: skema === 'B' ? num(r['Followers IG']) : (visit ? spend / visit : 0),
      cpm: impression ? (spend / impression) * 1000 : 0,
      frekuensi: reach ? impression / reach : 0,
      skema,
    });
  }

  // ============ 2. tabel Linktree ============
  if (skema === 'A' && typeof r['Linktree'] === 'string' && r['Linktree'].trim()
      && !isKosong(r['col_16'])) {
    const label = r['Linktree'].trim();
    if (label !== 'Most clicked content') linktreeRingkasan[label] = num(r['col_16']);
  }
  if (skema === 'B') {
    const tlt = parseTglUS(r['Linktree']);
    if (tlt) tglLtAktif = tlt;
    if (tglLtAktif && !isKosong(r['1-30 Juni 2026'])) {
      linktreeHarian.push({
        tanggal: tglLtAktif,
        views: num(r['1-30 Juni 2026']),
        clicks: num(r['col_15']),
        shopee: num(r['col_16']),
        wa: num(r['col_17']),
        maps: num(r['col_18']),
        tiktok: num(r['col_19']),
        website: num(r['col_20']),
      });
      tglLtAktif = null;
    }

    // ============ 3. tabel leads WA / closing ============
    const twa = parseTglUS(r['col_22']);
    if (twa) tglWaAktif = twa;
    if (tglWaAktif && !isKosong(r['col_27'])) {
      leadsWa.push({
        tanggal: tglWaAktif,
        voucher: num(r['col_23']),
        linktree: num(r['col_24']),
        website: num(r['col_25']),
        iklan: num(r['col_26']),
        totalChatBaru: num(r['col_27']),
        closing: num(r['col_28']),
        qty: num(r['col_29']),
        omset: num(r['col_30']),
        sumberClosing: isKosong(r['col_31']) || r['col_31'] === '-' ? null : String(r['col_31']).trim(),
      });
      tglWaAktif = null;
    }
  }
}

return [{
  json: {
    _source: 'ads',
    jumlahBarisIklan: iklan.length,
    iklan,
    linktreeHarian,
    leadsWa,
    linktreeRingkasan,
  },
}];

// ============================================================
// CODE NODE 3 — "Marketing Report"
// Mode: Run Once for All Items
// Input : Merge (Append) dari "Normalisasi Sales" + "Normalisasi Ads"
// Output: 1 item { laporan (HTML Telegram), data (JSON terstruktur) }
// ============================================================

const semua = $input.all().map(i => i.json);
const S = semua.find(x => x._source === 'sales') || {};
const A = semua.find(x => x._source === 'ads') || {};

const bb = S.bulanBerjalan || {};       // Juli 2026
const bl = S.bulanSebelumnya || {};     // Juni 2026
const yy = S.tahunLalu || {};           // Juli 2025

// ---------- formatter ----------
const rp = n => 'Rp' + Math.round(Number(n) || 0).toLocaleString('id-ID');
const rb = n => {
  const v = Math.round(Number(n) || 0);
  if (Math.abs(v) >= 1e9) return 'Rp' + (v / 1e9).toFixed(2) + ' M';
  if (Math.abs(v) >= 1e6) return 'Rp' + (v / 1e6).toFixed(1) + ' jt';
  if (Math.abs(v) >= 1e3) return 'Rp' + (v / 1e3).toFixed(0) + ' rb';
  return 'Rp' + v;
};
const angka = n => Math.round(Number(n) || 0).toLocaleString('id-ID');
const pct = n => ((Number(n) || 0) * 100).toFixed(2) + '%';
const dec = (n, d = 2) => (Number(n) || 0).toFixed(d);
const bagi = (a, b) => (Number(b) ? Number(a) / Number(b) : 0);

function delta(sekarang, pembanding) {
  const a = Number(sekarang) || 0, b = Number(pembanding) || 0;
  const selisih = a - b;
  const persen = b ? selisih / b : 0;
  const naik = selisih >= 0;
  return { selisih, persen, naik, tanda: naik ? '▲' : '▼', teks: (naik ? '+' : '') + pct(persen) };
}

// ---------- agregasi iklan ----------
const iklan = Array.isArray(A.iklan) ? A.iklan : [];
const bulanTerbaru = iklan.length
  ? iklan.map(x => x.tanggal.slice(0, 7)).sort().pop()
  : null;
const iklanBulanIni = iklan.filter(x => x.tanggal.slice(0, 7) === bulanTerbaru);

function agregat(list) {
  const r = list.reduce((a, x) => {
    a.spend += x.spend; a.ppn += x.ppn;
    a.impression += x.impression; a.reach += x.reach; a.igVisit += x.igVisit;
    a.chatWa += x.chatWa; a.followersIg += x.followersIg;
    a.followersFanpage += x.followersFanpage;
    return a;
  }, { spend: 0, ppn: 0, impression: 0, reach: 0, igVisit: 0, chatWa: 0, followersIg: 0, followersFanpage: 0 });
  r.spendPpn = r.spend + r.ppn;
  r.ctr = bagi(r.igVisit, r.impression);
  r.cpc = bagi(r.spend, r.igVisit);
  r.cpm = bagi(r.spend, r.impression) * 1000;
  r.frekuensi = bagi(r.impression, r.reach);
  r.hari = new Set(list.map(x => x.tanggal)).size;
  return r;
}
const meta = agregat(iklanBulanIni);

// per produk / campaign
const perProduk = {};
for (const x of iklanBulanIni) {
  const k = x.produk || x.campaign;
  if (!perProduk[k]) perProduk[k] = { produk: k, spend: 0, impression: 0, igVisit: 0, hari: new Set() };
  perProduk[k].spend += x.spend;
  perProduk[k].impression += x.impression;
  perProduk[k].igVisit += x.igVisit;
  perProduk[k].hari.add(x.tanggal);
}
const produkList = Object.values(perProduk).map(p => ({
  produk: p.produk,
  spend: p.spend,
  impression: p.impression,
  igVisit: p.igVisit,
  hari: p.hari.size,
  ctr: bagi(p.igVisit, p.impression),
  cpc: bagi(p.spend, p.igVisit),
  cpm: bagi(p.spend, p.impression) * 1000,
  porsiSpend: bagi(p.spend, meta.spend),
})).sort((a, b) => b.spend - a.spend);

const paling = [...produkList].filter(p => p.igVisit > 0).sort((a, b) => a.cpc - b.cpc);
const campaignTerhemat = paling.slice(0, 3);
const campaignTermahal = paling.slice(-3).reverse();

// ---------- linktree & leads WA ----------
const lt = (A.linktreeHarian || []).filter(x => !bulanTerbaru || x.tanggal.slice(0, 7) === bulanTerbaru);
const funnel = lt.reduce((a, x) => {
  a.views += x.views; a.clicks += x.clicks; a.shopee += x.shopee;
  a.wa += x.wa; a.maps += x.maps; a.tiktok += x.tiktok; a.website += x.website;
  return a;
}, { views: 0, clicks: 0, shopee: 0, wa: 0, maps: 0, tiktok: 0, website: 0 });
funnel.ctr = bagi(funnel.clicks, funnel.views);
funnel.biayaPerView = bagi(meta.spendPpn, funnel.views);
funnel.biayaPerClick = bagi(meta.spendPpn, funnel.clicks);

const wa = (A.leadsWa || []).filter(x => !bulanTerbaru || x.tanggal.slice(0, 7) === bulanTerbaru);
const leads = wa.reduce((a, x) => {
  a.voucher += x.voucher; a.linktree += x.linktree; a.website += x.website;
  a.iklan += x.iklan; a.totalChat += x.totalChatBaru;
  a.closing += x.closing; a.qty += x.qty; a.omset += x.omset;
  return a;
}, { voucher: 0, linktree: 0, website: 0, iklan: 0, totalChat: 0, closing: 0, qty: 0, omset: 0 });
leads.konversi = bagi(leads.closing, leads.totalChat);
leads.aov = bagi(leads.omset, leads.closing);
leads.roas = bagi(leads.omset, meta.spendPpn);

// ---------- metrik penjualan ----------
const rk = bb.ringkasan || {}, rkL = bl.ringkasan || {}, rkY = yy.ringkasan || {};
const aov = bagi(rk.totalOmset, rk.totalTerjual);
const aovL = bagi(rkL.totalOmset, rkL.totalTerjual);

const dOmsetMoM = delta(rk.totalOmset, rkL.totalOmset);
const dOmsetYoY = delta(rk.totalOmset, rkY.totalOmset);
const dTerjualMoM = delta(rk.totalTerjual, rkL.totalTerjual);
const dSpendMoM = delta(rk.spendAdsPpn, rkL.spendAdsPpn);
const dRoasMoM = delta(rk.roasTotal, rkL.roasTotal);
const dBiayaMoM = delta(rk.biayaPromosiPerPcs, rkL.biayaPromosiPerPcs);

// omset harian terbaik / terburuk
const harian = (bb.harian || []).filter(d => d.omset > 0);
const urut = [...harian].sort((a, b) => b.omset - a.omset);
const hariTerbaik = urut[0] || null;
const hariTerburuk = urut[urut.length - 1] || null;
const rataHarian = bagi(harian.reduce((a, d) => a + d.omset, 0), harian.length);

// ---------- insight otomatis ----------
const insight = [];
if (dRoasMoM.selisih < 0) {
  insight.push(`ROAS turun ${dec(Math.abs(dRoasMoM.selisih))} poin vs bulan lalu (${dec(rkL.roasTotal)} ke ${dec(rk.roasTotal)}), sementara spend ${dSpendMoM.teks}. Efisiensi iklan melemah.`);
} else {
  insight.push(`ROAS naik ${dec(dRoasMoM.selisih)} poin ke ${dec(rk.roasTotal)}. Belanja iklan makin efisien.`);
}
if (dBiayaMoM.selisih > 0) {
  insight.push(`Biaya promosi per pcs naik ${rp(dBiayaMoM.selisih)} jadi ${rp(rk.biayaPromosiPerPcs)}. Cek campaign dengan CPC tertinggi.`);
}
if ((bb.tiktok || {}).roas > (bb.shopee || {}).roas) {
  insight.push(`TikTok (ROAS ${dec((bb.tiktok || {}).roas)}) unggul dari Shopee (ROAS ${dec((bb.shopee || {}).roas)}). Pertimbangkan geser porsi budget.`);
} else {
  insight.push(`Shopee (ROAS ${dec((bb.shopee || {}).roas)}) masih lebih efisien dari TikTok (ROAS ${dec((bb.tiktok || {}).roas)}).`);
}
if (campaignTerhemat[0]) {
  insight.push(`Campaign paling murah per visit: ${campaignTerhemat[0].produk} (CPC ${rp(campaignTerhemat[0].cpc)}).`);
}
if (campaignTermahal[0] && campaignTermahal[0].cpc > meta.cpc * 2) {
  insight.push(`${campaignTermahal[0].produk} boros: CPC ${rp(campaignTermahal[0].cpc)} atau ${dec(bagi(campaignTermahal[0].cpc, meta.cpc), 1)}x rata-rata akun.`);
}
if (leads.totalChat && leads.konversi < 0.15) {
  insight.push(`Konversi chat WA cuma ${pct(leads.konversi)} dari ${angka(leads.totalChat)} chat. Follow-up CS perlu dibenahi.`);
}

// ---------- susun laporan (HTML Telegram) ----------
const L = [];
L.push(`<b>LAPORAN MARKETING QUDAMAH</b>`);
L.push(`Periode: <b>${bb.periode || '-'}</b> (${bb.hariTerisi || 0} hari)`);
L.push('');

L.push(`<b>1. PENJUALAN</b>`);
L.push(`Omset: <b>${rp(rk.totalOmset)}</b>`);
L.push(`  vs ${bl.periode || 'bln lalu'}: ${dOmsetMoM.tanda} ${dOmsetMoM.teks} (${rb(dOmsetMoM.selisih)})`);
L.push(`  vs ${yy.periode || 'thn lalu'}: ${dOmsetYoY.tanda} ${dOmsetYoY.teks} (${rb(dOmsetYoY.selisih)})`);
L.push(`Produk terjual: ${angka(rk.totalTerjual)} pcs (${dTerjualMoM.tanda} ${dTerjualMoM.teks})`);
L.push(`Resi: ${angka(rk.totalResi)} | AOV: ${rp(aov)} (bln lalu ${rp(aovL)})`);
L.push(`Rata-rata omset/hari: ${rp(rataHarian)}`);
if (hariTerbaik) L.push(`Tertinggi: ${hariTerbaik.tanggal} ${rb(hariTerbaik.omset)} | Terendah: ${hariTerburuk.tanggal} ${rb(hariTerburuk.omset)}`);
L.push('');

L.push(`<b>2. EFISIENSI IKLAN (TOTAL)</b>`);
L.push(`Spend ads +ppn: ${rp(rk.spendAdsPpn)} (${dSpendMoM.tanda} ${dSpendMoM.teks})`);
L.push(`ROAS total: <b>${dec(rk.roasTotal)}</b> (bln lalu ${dec(rkL.roasTotal)})`);
L.push(`Biaya promosi/pcs: ${rp(rk.biayaPromosiPerPcs)} (bln lalu ${rp(rkL.biayaPromosiPerPcs)})`);
L.push(`Komisi affiliate: ${rp(rk.komisiAffiliate)} | Koin penjual: ${rp(rk.koinPenjual)}`);
L.push('');

L.push(`<b>3. PER CHANNEL</b>`);
const ch = [
  ['Shopee', bb.shopee || {}, bl.shopee || {}],
  ['TikTok', bb.tiktok || {}, bl.tiktok || {}],
];
for (const [nama, c, cl] of ch) {
  const dr = delta(c.roas, cl.roas);
  L.push(`<b>${nama}</b>: omset ${rb(c.omset)} | ${angka(c.terjual)} pcs`);
  L.push(`  ads ${rb(c.ads)} | ROAS ${dec(c.roas)} (${dr.tanda} ${dec(dr.selisih)}) | ${rp(c.biayaPerPcs)}/pcs`);
}
L.push('');

L.push(`<b>4. META ADS</b>`);
L.push(`Spend +ppn: ${rp(meta.spendPpn)} (${meta.hari} hari aktif)`);
L.push(`Impresi ${angka(meta.impression)} | Reach ${angka(meta.reach)} | Freq ${dec(meta.frekuensi)}`);
L.push(`IG visit ${angka(meta.igVisit)} | CTR ${pct(meta.ctr)} | CPC ${rp(meta.cpc)} | CPM ${rp(meta.cpm)}`);
L.push(`Followers IG baru: ${angka(meta.followersIg)}`);
L.push('');

L.push(`<b>5. TOP CAMPAIGN (by spend)</b>`);
produkList.slice(0, 5).forEach((p, i) => {
  L.push(`${i + 1}. ${p.produk} - ${rb(p.spend)} (${pct(p.porsiSpend)}) | CPC ${rp(p.cpc)} | CTR ${pct(p.ctr)}`);
});
L.push('');

L.push(`<b>6. FUNNEL LINKTREE</b>`);
L.push(`Views ${angka(funnel.views)} -> Clicks ${angka(funnel.clicks)} (CTR ${pct(funnel.ctr)})`);
L.push(`Shopee ${angka(funnel.shopee)} | WA ${angka(funnel.wa)} | Maps ${angka(funnel.maps)} | TikTok ${angka(funnel.tiktok)} | Web ${angka(funnel.website)}`);
L.push(`Biaya/view ${rp(funnel.biayaPerView)} | Biaya/click ${rp(funnel.biayaPerClick)}`);
L.push('');

L.push(`<b>7. LEADS WA</b>`);
L.push(`Chat baru ${angka(leads.totalChat)} (voucher ${angka(leads.voucher)}, linktree ${angka(leads.linktree)}, web ${angka(leads.website)}, iklan ${angka(leads.iklan)})`);
L.push(`Closing ${angka(leads.closing)} | ${angka(leads.qty)} pcs | omset ${rp(leads.omset)}`);
L.push(`Konversi ${pct(leads.konversi)} | AOV ${rp(leads.aov)} | ROAS meta ${dec(leads.roas)}`);
L.push('');

L.push(`<b>8. CATATAN</b>`);
insight.forEach(t => L.push(`- ${t}`));

const laporan = L.join('\n');

return [{
  json: {
    laporan,
    data: {
      periode: bb.periode,
      penjualan: {
        omset: rk.totalOmset, terjual: rk.totalTerjual, resi: rk.totalResi,
        aov, rataHarian, hariTerbaik, hariTerburuk,
        momOmset: dOmsetMoM, yoyOmset: dOmsetYoY, momTerjual: dTerjualMoM,
      },
      iklanTotal: {
        spendPpn: rk.spendAdsPpn, roas: rk.roasTotal,
        biayaPerPcs: rk.biayaPromosiPerPcs,
        komisiAffiliate: rk.komisiAffiliate, koinPenjual: rk.koinPenjual,
        momSpend: dSpendMoM, momRoas: dRoasMoM, momBiaya: dBiayaMoM,
      },
      channel: { shopee: bb.shopee, tiktok: bb.tiktok },
      meta,
      perProduk: produkList,
      campaignTerhemat, campaignTermahal,
      funnelLinktree: funnel,
      leadsWa: leads,
      insight,
    },
  },
}];

// ============================================================
// NODE: "Pecah Pesan Telegram"
// Tipe: Code, mode "Run Once for All Items"
// Posisi: setelah "Hitung Metrik Harian", sebelum node Telegram
//
// Memecah field pesan jadi beberapa item, satu item = satu pesan Telegram.
// Pemotongan diusahakan di batas blok (baris kosong), lalu baris,
// dan baru dipotong paksa kalau satu baris memang lebih panjang dari batas.
// ============================================================

const BATAS = 3800;              // aman di bawah limit 4096 milik Telegram
const NOMOR_BAGIAN = true;       // tambahkan penanda (1/3) di akhir tiap pesan
const FIELD = 'pesan';           // nama field sumber teks

const potongPanjang = (teks, batas) => {
  const out = [];
  let sisa = teks;
  while (sisa.length > batas) {
    out.push(sisa.slice(0, batas));
    sisa = sisa.slice(batas);
  }
  if (sisa.length > 0) out.push(sisa);
  return out;
};

// Pecah teks jadi unit terkecil yang masih utuh: blok, lalu baris, lalu paksa
function unitTeks(teks, batas) {
  const unit = [];
  for (const blok of String(teks).split('\n\n')) {
    if (blok.length <= batas) { unit.push(blok); continue; }
    let kumpul = '';
    for (const baris of blok.split('\n')) {
      if (baris.length > batas) {
        if (kumpul) { unit.push(kumpul); kumpul = ''; }
        unit.push(...potongPanjang(baris, batas));
        continue;
      }
      if ((kumpul + '\n' + baris).length > batas) { unit.push(kumpul); kumpul = baris; }
      else kumpul = kumpul ? kumpul + '\n' + baris : baris;
    }
    if (kumpul) unit.push(kumpul);
  }
  return unit.filter(u => u.trim() !== '');
}

function pecah(teks, batas) {
  const unit = unitTeks(teks, batas);
  const bagian = [];
  let kumpul = '';
  for (const u of unit) {
    if (kumpul === '') { kumpul = u; continue; }
    if ((kumpul + '\n\n' + u).length > batas) { bagian.push(kumpul); kumpul = u; }
    else kumpul = kumpul + '\n\n' + u;
  }
  if (kumpul) bagian.push(kumpul);
  return bagian.length > 0 ? bagian : [''];
}

const keluar = [];
for (const item of $input.all()) {
  const asal = item.json || {};
  const teks = String(asal[FIELD] || '');
  if (teks.trim() === '') continue;

  // Sisakan ruang untuk penanda bagian
  const cadangan = NOMOR_BAGIAN ? 12 : 0;
  const bagian = pecah(teks, BATAS - cadangan);

  bagian.forEach((isi, i) => {
    const label = NOMOR_BAGIAN && bagian.length > 1 ? '\n\n(' + (i + 1) + '/' + bagian.length + ')' : '';
    keluar.push({
      json: {
        pesan: isi + label,
        bagian: i + 1,
        totalBagian: bagian.length,
        panjang: (isi + label).length,
        // ringkas hanya ikut di pesan pertama supaya payload tidak berlipat
        ringkas: i === 0 ? asal.ringkas : undefined
      }
    });
  });
}

if (keluar.length === 0) {
