.bar-row{grid-template-columns:88px 1fr 78px;font-size:11.5px}
.grid{grid-template-columns:1fr}
}
</style></head><body>
<div class="wrap">
<header>
  <h1>Dashboard Finansial Qudamah</h1>
  <div class="meta">Periode ${esc(periode.labelBulan)} &middot; Data per ${esc(periode.tanggalAcuan)} &middot; ${esc(m.accountCount)} akun</div>
</header>
<nav>${navHtml}</nav>
${paneHtml}
<footer>Dibuat otomatis ${esc(waktuCetak)} WIB dari Accurate ERP</footer>
</div>
<script>
document.querySelectorAll('.tab').forEach(function(btn){
  btn.addEventListener('click', function(){
    document.querySelectorAll('.tab').forEach(function(b){b.classList.remove('active');});
    document.querySelectorAll('.pane').forEach(function(p){p.classList.remove('active');});
    btn.classList.add('active');
    var el = document.getElementById('p-' + btn.dataset.t);
    if (el) el.classList.add('active');
    window.scrollTo({top:0,behavior:'smooth'});
  });
});
</script>
</body></html>`;

const namaFile = `dashboard-finansial-${periode.bulanKey}.html`;

return [{
  json: {
    html,
    namaFile,
    periode: periode.labelBulan,
    basisBulanan: bulanan.basisTipe || null,
    bulananLayakDilaporkan: bulanan.layakDilaporkan,
    ukuranKb: Math.round(Buffer.byteLength(html, 'utf8') / 1024),
  },
  binary: {
    data: {
      data: Buffer.from(html, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName: namaFile,
      fileExtension: 'html',
    },
  },
}];

// ============================================================
// Node: Baca Perintah
// Mengurai pesan Telegram menjadi mode kerja workflow.
//
// Aturan pemilahan:
//   diawali '/'  -> perintah. Dikenal jadi mode kerjanya, tidak
//                   dikenal dibalas daftar perintah.
//   teks biasa   -> lanjutan percakapan konsultasi. Dijawab dari
//                   memori tanpa menarik ulang data.
//   bukan teks   -> diabaikan (stiker, foto, lokasi).
//
// ------------------------------------------------------------
// AKSES
// BATASI_KE_DAFTAR_IZIN = false berarti bot terbuka untuk SIAPA PUN
// yang menemukannya di Telegram, dan balasannya dikirim ke chat id
// pengirim masing-masing. Tidak ada chat yang berstatus ditolak
// selama flag ini false.
//
// Konsekuensinya: siapa pun yang tahu nama bot ini bisa menarik laba
// rugi, neraca, posisi kas, dan nilai persediaan Qudamah, serta
// memicu eksekusi berbayar berulang kali.
//
// Untuk menguncinya kembali, ubah satu baris di bawah menjadi true.
// Kalau nanti dikunci lagi, pastikan chat id di dalam array ditulis
// sebagai string tanpa spasi berlebih, karena perbandingannya persis.
// ------------------------------------------------------------
const BATASI_KE_DAFTAR_IZIN = false;
const CHAT_DIIZINKAN = ['YOUR_TELEGRAM_CHAT_ID'];

const PETA_PERINTAH = {
  '/sales': 'harian',
  '/finance': 'finansial',
  '/aiconsult': 'konsultasi',
};

const pesan = $json.message || $json.edited_message || {};
const teks = String(pesan.text || '').trim();
const chatId = String((pesan.chat && pesan.chat.id) || '').trim();
const nama = String((pesan.from && pesan.from.first_name) || 'Pengguna');
const username = String((pesan.from && pesan.from.username) || '');

const potongan = teks.split(/\s+/);
let perintah = String(potongan[0] || '').toLowerCase();
// Di grup, Telegram mengirim perintah sebagai /sales@NamaBot
const posAt = perintah.indexOf('@');
if (posAt > 0) perintah = perintah.slice(0, posAt);

const adalahPerintah = perintah.charAt(0) === '/';
const argumen = teks.slice(String(potongan[0] || '').length).trim();

const daftarBersih = CHAT_DIIZINKAN.map(x => String(x).trim());
const ditolak = BATASI_KE_DAFTAR_IZIN && daftarBersih.indexOf(chatId) === -1;

let mode = null;
let pertanyaan = '';
let status;

if (ditolak) {
  status = 'ditolak';
} else if (!teks) {
  status = 'abaikan';
} else if (adalahPerintah) {
  mode = PETA_PERINTAH[perintah] || null;
  pertanyaan = argumen;
  status = mode ? 'ok' : 'tidak dikenal';
} else {
  mode = 'lanjutan';
  pertanyaan = teks;
  status = 'lanjutan';
}

return [{
  json: {
    status,
    mode,
    perintah: adalahPerintah ? perintah : '(lanjutan percakapan)',
    pertanyaan,
    chatId,
    nama,
    username,
    teksAsli: teks,
    aksesTerbuka: !BATASI_KE_DAFTAR_IZIN,
    daftarPerintah: Object.keys(PETA_PERINTAH),
  },
}];

// ============================================================
// Node: Tentukan Mode
// Satu-satunya penentu apa yang dikerjakan dan apa yang dikirim.
// Semua gate hilir membaca flag dari sini, tidak ada gate yang
// menghitung sendiri.
//
// Ada tiga pintu masuk:
//   Jadwal Harian 07:00           -> laporan sales harian
//   Jadwal Mingguan Minggu 10:00  -> laporan finance mingguan
//   Telegram Trigger              -> perintah atau lanjutan percakapan
// ============================================================

// Chat tujuan untuk eksekusi TERJADWAL saja. Eksekusi yang dipicu
// perintah membalas ke chat pengirimnya. Isi dengan chat id berupa
// angka dalam tanda kutip, BUKAN ekspresi, karena node Code tidak
// mengevaluasi ekspresi n8n di dalam string.
const CHAT_DEFAULT = 'YOUR_TELEGRAM_CHAT_ID';

// Nama node pemicu finance. Kalau node itu di-rename di canvas,
// nilai di bawah WAJIB ikut diubah, kalau tidak setiap eksekusi
// terjadwal akan dianggap jadwal harian.
const NODE_PERINTAH = 'Baca Perintah';
const NODE_JADWAL_FINANCE = 'Jadwal Mingguan Minggu 10:00';

let mode = null;
let pertanyaan = '';
let chatId = CHAT_DEFAULT;
let nama = '';
let perintahAsal = '';

// 1. Dipicu perintah Telegram?
try {
  const p = $(NODE_PERINTAH).first().json;
  if (p && p.mode) {
    mode = p.mode;
    pertanyaan = p.pertanyaan || '';
    chatId = p.chatId || CHAT_DEFAULT;
    nama = p.nama || '';
    perintahAsal = p.perintah || '';
  }
} catch (e) { /* bukan dari Telegram */ }

// 2. Bukan perintah. Cek jadwal mana yang menyalakan eksekusi ini.
if (!mode) {
  try {
    $(NODE_JADWAL_FINANCE).first();
    mode = 'jadwal-finance';
    perintahAsal = '(jadwal mingguan)';
  } catch (e) {
    mode = 'jadwal-sales';
    perintahAsal = '(jadwal harian)';
  }
}

// ------------------------------------------------------------
// Flag kerja
// ------------------------------------------------------------
// Mode 'lanjutan' adalah balasan teks biasa atas jawaban konsultasi.
// Dijawab dari memori, jadi seluruh penarikan data dilewati dan
// balasannya hitungan detik, bukan menit.
const tarikData = mode !== 'lanjutan';

// Metrik sales dipakai dua kali, sebagai laporan dan sebagai konteks
// untuk AI Konsultan lewat node Gabung Konteks Konsultasi. Selama
// pipeline jalan, branch ini harus ikut jalan agar input Merge itu
// tidak pernah kosong.
const prosesSales = tarikData;

// ------------------------------------------------------------
// Flag kirim. Ini yang menentukan pesan mana yang keluar.
//   /sales, jadwal harian     -> hanya laporan sales
//   /finance, jadwal mingguan -> hanya laporan finance
//   /aiconsult, lanjutan      -> hanya jawaban konsultasi
// ------------------------------------------------------------
const kirimSales = mode === 'harian' || mode === 'jadwal-sales';
const kirimFinansial = mode === 'finansial' || mode === 'jadwal-finance';
const kirimKonsultasi = mode === 'konsultasi';

return [{
  json: {
    mode,
    perintahAsal,
    pertanyaan,
    chatId,
    nama,
    tarikData,
    prosesSales,
    // nama lama dipertahankan agar gate yang sudah ada tetap terbaca
    prosesHarian: prosesSales,
    kirimSales,
    kirimHarian: kirimSales,
    kirimFinansial,
    kirimKonsultasi,
    dipicuOleh: perintahAsal,
    waktuMulai: new Date().toISOString(),
  },
}];

// ============================================================
// Node: Siapkan Payload Konsultasi
// Punya dua jalur masuk:
//   1. Gabung Konteks Konsultasi -> perintah /aiconsult, data segar
//      dari laporan sales dan laporan finance.
//   2. Jalur Lanjutan -> balasan teks biasa, dijawab dari memori
//      percakapan tanpa menarik data.
// Kedua node sumber dibaca dengan try/catch karena pada jalur
// lanjutan keduanya memang tidak tereksekusi.
// ============================================================
const BATAS_KARAKTER_SALES = 14000;

const mode = $('Tentukan Mode').first().json;
const lanjutan = mode.mode === 'lanjutan';

// --- Sumber 1: laporan finansial ---
let fin = null;
if (!lanjutan) {
  try { fin = $('Hitung Laba Rugi & Neraca').first().json; } catch (e) { fin = null; }
}

// --- Sumber 2: laporan sales / operasional harian ---
let sales = null;
let salesDipangkas = false;
if (!lanjutan) {
  try {
    const h = $('Hitung Metrik Harian').first().json;
    const s = JSON.stringify(h);
    if (s.length > BATAS_KARAKTER_SALES) {
      salesDipangkas = true;
      sales = { catatan: 'Data sales dipangkas karena terlalu besar untuk satu prompt.', cuplikan: s.slice(0, BATAS_KARAKTER_SALES) };
    } else {
      sales = h;
    }
  } catch (e) {
    sales = null;
  }
}

const laporanFinance = fin ? {
  dataQuality: fin.dataQuality,
  periode: fin.periode,
  penjualanBulanBerjalan: fin.penjualanMTD,
  bulanan: fin.bulanan,
  tahunan: fin.tahunan,
  rataRataBulanan: fin.rataRataBulanan,
  posisi: fin.posisi,
  diagnostikNeraca: {
    seimbang: (fin.diagnostikNeraca || {}).seimbang,
    selisihIdentitas: (fin.diagnostikNeraca || {}).selisihIdentitas,
    dugaanPenyebab: (fin.diagnostikNeraca || {}).dugaanPenyebab,
  },
} : null;

const pertanyaan = (mode.pertanyaan || '').trim()
  || 'Beri ringkasan kondisi bisnis Qudamah saat ini dan tiga hal yang paling perlu diperhatikan minggu ini.';

const ketersediaan = {
  lanjutanDariMemori: lanjutan,
  laporanSales: Boolean(sales),
  laporanSalesDipangkas: salesDipangkas,
  laporanFinance: Boolean(laporanFinance),
  dihasilkanPada: new Date().toISOString(),
};

return [{
  json: {
    pertanyaan,
    lanjutan,
    ketersediaan,
    payload: JSON.stringify({
      ketersediaan,
      laporanSales: sales,
      laporanFinance,
    }),
  },
}];

